'use strict';

// MODULES //

var tape = require( 'tape' );
var OrdinalScale = require( '@stdlib/plot/vega/scale/ordinal' );
var DiscreteScale = require( '@stdlib/plot/vega/scale/discrete' );
var Scale = require( '@stdlib/plot/vega/scale/base/ctor' );
var isDiscreteScale = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isDiscreteScale, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided a discrete scale instance', function test( t ) {
	var values;
	var bool;
	var i;

	values = [
		new OrdinalScale({
			'name': 'yScale'
		}),
		new DiscreteScale({
			'name': 'zScale',
			'type': 'ordinal'
		})
	];
	for ( i = 0; i < values.length; i++ ) {
		bool = isDiscreteScale( values[ i ] );
		t.strictEqual( bool, true, 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});

tape( 'the function returns `false` if not provided a discrete scale instance', function test( t ) {
	var values;
	var bool;
	var i;

	values = [
		new Scale({
			'name': 'xScale',
			'type': 'linear'
		}),
		'',
		'beep',
		'boop',
		'foo',
		'bar',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		bool = isDiscreteScale( values[ i ] );
		t.strictEqual( bool, false, 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});
